function daysUntilWarmer(temps) {
  const answer = new Array(temps.length).fill(0);
  const waiting = []; // indexes; temps decrease from bottom to top
  for (let today = 0; today < temps.length; today++) {
    while (waiting.length > 0 && temps[today] > temps[waiting[waiting.length - 1]]) {
      const earlierDay = waiting.pop();
      answer[earlierDay] = today - earlierDay;
    }
    waiting.push(today);
  }
  return answer;
}

