let seed = 23;
const rand = (m) => { seed = (seed * 48271) % 2147483647; return seed % m; };
function brute(t) {
  const a = new Array(t.length).fill(0);
  for (let i = 0; i < t.length; i++) for (let j = i + 1; j < t.length; j++) if (t[j] > t[i]) { a[i] = j - i; break; }
  return a;
}
for (let k = 0; k < 40; k++) {
  const t = Array.from({ length: rand(14) }, () => rand(9) - 4);
  assertEqual(daysUntilWarmer(t), brute(t), JSON.stringify(t));
}
